/* Irish Gaelic Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Sean": "God is gracious — Hebrew Yohanan", "Siobhan": "God is gracious — Hebrew, via Joan", "Padraig": "nobleman — Latin Patricius", "Aoife": "beauty, radiance — Irish aoibh", "Cian": "ancient, enduring — Irish", "Niamh": "bright, radiant — Irish", "O'Brien": "The great surname of Brian Boru's line.", "O'Connor": "A royal Connacht surname.", "MacCarthy": "The great Munster surname.", "Walsh": "The surname of the Welsh settlers, Breathnach."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Sean';
console.log(lookup(q));

